{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Temozolomide, a small neutral carboxamide-containing drug, has 100% oral bioavailability in patients, supporting high F for the neutral urea/carboxamide-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Tocainide has about 100% absolute oral bioavailability in healthy volunteers, demonstrating that small amide-containing molecules can avoid significant first-pass metabolism and achieve complete oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Thalidomide, a carbonyl-rich neutral heterocycle with moderate lipophilicity, shows 80-100% oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Phenylethylmalonamide, an aromatic primary amide, has at least 80% oral bioavailability in normal subjects, supporting high F for the amide-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Saccharin in the fed state has a fraction absorbed of 0.80 ± 0.05 versus IV, directly supporting high oral bioavailability under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Aspirin/salicylate systemic availability is 65-74% after oral administration in humans, providing additional high-transfer evidence that small, moderately lipophilic molecules can exceed the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer human oral bioavailability measurements for related small molecules are well above 20%, mostly 62-100%, including a fed-state measurement of 80%. The query's neutral, low-MW, moderately lipophilic carboxamide/urea profile is consistent with complete absorption, and no affirmative evidence supports F<20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is included; inference relies on high-transfer analogues.",
    "Fed-state data are limited to saccharin; food effects on the query's absorption rate or solubility are not directly measured.",
    "Some analogues show interindividual variability in F, but their mean values remain above the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

